"""Second-round additions to the existing manuscript, with no archived chapters removed."""
from pathlib import Path
from html import escape
import json,re
ROOT=Path(__file__).resolve().parents[1]
ASSET=ROOT.name

def scene(name,alt,caption):
    w,h={'neonatal-screening':(1000,340),'oral-trial-timeline':(1000,370),'clinical-classification':(1000,345),'infant-counterfactual':(900,275),'reproducibility-chain':(1000,325)}[name]
    return f'<figure class="clinical-scene"><img src="{ASSET}/figures/{name}.svg" width="{w}" height="{h}" alt="{escape(alt)}" loading="lazy"><figcaption>{caption}</figcaption></figure>'

def citation():
    authors='Pinaki Panigrahi; Sailajanandan Parida; Nimai C. Nanda; Radhanath Satpathy; Lingaraj Pradhan; Dinesh S. Chandel; Lorena Baccaglini; Arjit Mohapatra; Subhranshu S. Mohapatra; Pravas R. Misra; Rama Chaudhry; Hegang H. Chen; Judith A. Johnson; J. Glenn Morris Jr.; Nigel Paneth; Ira H. Gewolb'
    return f'''<aside class="paper-citation" aria-labelledby="paper-title"><div class="chapter-label">The original research paper · full authorship</div><h2 id="paper-title">A randomized synbiotic trial to prevent sepsis among infants in rural India</h2><p class="paper-authors">{authors}.</p><p><em>Nature</em> <strong>548</strong> (7668), 407–412 · August 24, 2017 (online August 16).</p><div class="citation-links"><a href="https://doi.org/10.1038/nature23480">Original article · DOI</a><a href="https://doi.org/10.5061/dryad.275d4">Open data and protocol</a><a href="https://doi.org/10.1038/nature25006">2018 corrigendum</a></div><p class="small">This independent educational reconstruction uses the released records and accessible study materials. The corrigendum governs the culture classifications; this page is not an author-issued reanalysis.</p></aside>'''

def enhance_parts(parts):
    parts['trial']=parts['trial'].replace('</section>',scene('neonatal-screening','Caregiver, infant scale and clinician with eligibility boundaries.','Published design · Original conceptual screening illustration; eligibility boundaries limit transportability.')+'</section>',1)
    start=parts['trial'].index('id="actual-design"');end=parts['trial'].index('</section>',start)
    parts['trial']=parts['trial'][:end]+scene('oral-trial-timeline','Two balanced oral strategies and an age-scaled follow-up timeline.','Published design · Coded oral preparations, seven daily doses, and surveillance to age 60 days. Content is revealed here for teaching; actual allocation was masked.')+parts['trial'][end:]
    # Place microbiology beside the clinical definitions, rather than introducing a new diagnostic claim.
    idx=parts['trial'].find('id="corrected-outcomes"')
    if idx<0:idx=parts['trial'].find('id="trial-outcomes"')
    if idx>=0:
        end=parts['trial'].find('</section>',idx)
        parts['trial']=parts['trial'][:end]+scene('clinical-classification','Scientist with microscope and three corrected released sepsis categories.','Published categories / reproduced counts · A + B + C = 319 sepsis cases. The 94 additional culture-negative evaluations cannot be isolated from a dedicated flag in the release. This scene is not a diagnostic algorithm.')+parts['trial'][end:]
    else:
        parts['trial']+=scene('clinical-classification','Scientist and the three corrected sepsis categories.','Published categories / reproduced counts · Classification summary, not a diagnostic algorithm.')
    parts['causal-math']=parts['causal-math'].replace('<div class="formula">',scene('infant-counterfactual','One conceptual infant linked to two assignment-specific potential outcomes.','Synthetic conceptual illustration · For an adverse endpoint, Yᵢ(1) − Yᵢ(0) &lt; 0 represents benefit. Only one assignment outcome is observed; group contrasts estimate an average effect.')+'<div class="formula">',1)
    parts['causal-math']=parts['causal-math'].replace('<p>Consistency links','<p>The population average treatment effect is ATE = E[Yᵢ(1) − Yᵢ(0)]. The finite-enrolled-population analogue τ<sub>N</sub> below averages over these N infants. Neither identifies an individual infant’s unobserved outcome.</p><p>Consistency links',1)
    parts['effect-math']=parts['effect-math'].replace('<p id="toyResult"','<div id="toyIcons" class="grid two icon-comparison" aria-label="Synthetic event icon arrays"></div><svg id="toyBars" viewBox="0 0 800 145" class="risk-comparison" role="img" aria-label="Synthetic risks on the same zero to 100 percent scale"></svg><div id="toyEquations" class="substitution" aria-label="Effects computed from the current counts"></div><p id="toyResult"')
    parts['inference-math']+=methods_crosswalk()
    v=json.loads((ROOT/'data/independent_verification.json').read_text(encoding='utf-8'))
    baseline=json.loads((ROOT/'documentation/pre-refinement-summary.json').read_text(encoding='utf-8'))
    labels={'SEPSISDEATH':'Sepsis or death','CULTPOS':'Culture-positive A','SEPSISC':'pSBI–LRTI C','ABSCESS':'Abscess','DEATH':'Death'}
    rows=[]
    for key,label in labels.items():
        r=v['outcomes'][key];old=baseline['outcomes'][key];p=baseline['published'][key]
        f=lambda x:f'{x["rr"]:.3f} [{x["rr_ci"][0]:.3f}, {x["rr_ci"][1]:.3f}]'
        status='Counts and rounded interval agree' if key in ['SEPSISDEATH','DEATH'] else 'Counts agree; CI upper bound differs'
        rows.append(f'<tr><th scope="row">{label}</th><td>{f(old)}</td><td>{p[2]:.2f} [{p[3]:.2f}, {p[4]:.2f}]</td><td>{f(r)}</td><td>{status}</td></tr>')
    audit='''<h4>Independent second-pass verification</h4><p>A separate standard-library implementation reads the raw CSV, without importing the first analysis. All 12 outcome count pairs, six baseline mean/SD pairs and three alternate-population checks agree. “Before refinement” below means the saved aggregate output; recomputed intervals use the stated Katz method.</p><div class="table-wrap"><table><caption>Before refinement, publication, and independent recomputation · RR [95% CI]</caption><thead><tr><th>Endpoint</th><th>Before refinement</th><th>Published</th><th>Recomputed</th><th>Status</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><div class="notice audit-discrepancy"><strong>Additional p-value discrepancy.</strong> Table 2 reports mortality p = 0.526 and labels it Fisher’s exact test. For 6/2,278 versus 4/2,278, two-sided Fisher gives 0.753636; uncorrected Pearson gives 0.526635. This suggests a test-label discrepancy, but the original analysis code is unavailable. For omphalitis, published p = 0.014 differs from Pearson 0.012266 and Fisher 0.021052. These are documented disagreements, not grounds to alter records or assert which unpublished procedure was used.</div><p class="source-note"><a href="'''+ASSET+'''/analysis/independent-verification.md">Full independent comparison, including all endpoints and p-values</a>. This recheck confirms numerical reconstruction, not the completeness of clinical ascertainment.</p>'''
    # Add the audit inside the existing secondary results chapter.
    start=parts['empirical'].find('id="secondary-results"');end=parts['empirical'].find('</section>',start)
    assert start>=0 and end>=0
    parts['empirical']=parts['empirical'][:end]+audit+parts['empirical'][end:]
    parts['conclusion']=parts['conclusion'].replace('<h3>Reproducibility', '<h3>Reproducibility',1)
    start=parts['conclusion'].find('id="reproducibility"');end=parts['conclusion'].find('</section>',start)
    assert start>=0
    parts['conclusion']=parts['conclusion'][:end]+scene('reproducibility-chain','Original data to dictionary to code to aggregate result to publication comparison.','Reproducible workflow · The displayed primary RR is populated from the generated aggregate file. Disagreements remain explicit rather than being fitted away.')+parts['conclusion'][end:]
    parts['conclusion']=parts['conclusion'].replace('<ul class="resource-list">','<ul class="resource-list"><li><a href="'+ASSET+'/documentation/refinement-report.md">Latest refinement report, all changed files and browser validation</a></li>',1)
    parts={k:re.sub(r'<p class="small">Metadata:.*?</p>','<p class="small">Metadata: creation date follows the earliest Git history (August 9, 2026). Model GPT-6.1 Sol and reasoning High are the user-requested attribution for this refinement. Modified November 4, 2026.</p>',v,flags=re.S) for k,v in parts.items()}
    return parts

def enhance_originals(o):
    o['lab-balance-lab']=o['lab-balance-lab'].replace('<div class="control-row">','<div class="control-row"><label for="balanceN">Total sample <output id="balanceNOut">540</output></label><input id="balanceN" type="range" min="40" max="540" step="20" value="540"><button id="balanceRepeat" type="button">Add 200 randomizations</button><button id="balanceReset" type="button">Reset balance</button>',1)
    o['lab-balance-lab']=o['lab-balance-lab'].replace('</svg><p class="small">','</svg><svg id="balanceDistribution" class="distribution-svg" viewBox="0 0 800 240" role="img" aria-label="Distribution of age SMD over repeated complete randomizations"></svg><p id="balanceDistributionStatus" class="small" aria-live="polite"></p><p class="small">',1)
    o['lab-sampling']=o['lab-sampling'].replace('uses a fixed standard error of 0.055','uses SE = 0.055√(270/n), where n is per arm').replace('one approximate 95% interval','one interval at the selected confidence level')
    o['lab-sampling']=o['lab-sampling'].replace('<div class="control-row">','<div class="control-row"><label for="coverageLevel">Confidence level</label><select id="coverageLevel"><option value=".9">90%</option><option value=".95" selected>95%</option><option value=".99">99%</option></select><label for="coverageN">Per arm <output id="coverageNOut">270</output></label><input id="coverageN" type="range" min="50" max="1000" step="10" value="270"><button id="coverageReset" type="button">Reset coverage</button>',1)
    o['lab-power']=o['lab-power'].replace('a two-sided 5% test','a two-sided test at the selected significance level')
    o['lab-power']=o['lab-power'].replace('<div class="control-row">','<div class="control-row"><label for="powerAlpha">Significance α <output id="powerAlphaOut">5%</output></label><input id="powerAlpha" type="range" min="1" max="10" step="1" value="5"><button id="powerReset" type="button">Reset planning</button>',1)
    o['lab-power']=o['lab-power'].replace('<div class="matrix"','<svg id="hypothesisPlot" class="distribution-svg" viewBox="0 0 800 300" role="img" aria-label="Null and alternative sampling densities with rejection regions"></svg><p class="small">Horizontal scale: Z = estimated risk difference / null standard error. Blue is the null density; green is the assumed beneficial alternative. Peach tails mark rejection regions. The shaded area of the alternative outside the cutoffs is power. Both plots share the controls above.</p><div class="matrix"',1)
    o['lab-power']=o['lab-power'].replace('alpha = 5%','α = <span id="matrixAlpha">5%</span>').replace('Type II error, beta','Type II error, β = <span id="matrixBeta"></span>').replace('power = 1 minus beta','power = 1 − β = <span id="matrixPower"></span>')
    return o

def group_parameters(html):
    return re.sub(r'(<label\b[^>]*for="[^"]+"[^>]*>.*?</label>)(\s*<(?:input\b[^>]*|select\b[^>]*>.*?</select)>)',r'<div class="parameter">\1\2</div>',html,flags=re.S)

def methods_crosswalk():
    return r'''<section class="chapter" id="study-methods"><div class="chapter-label">Study methods · source-to-equation crosswalk</div><h3>Which calculations belong to the study?</h3><p>The accessible protocol, reporting summary, public tables and corrigendum document the design and broad analysis. The full article body and original SAS programs were not available for this reconstruction. The equations below explain or reconstruct those methods; they are not presented as quotations from an inaccessible manuscript.</p><div class="table-wrap"><table><caption>Documented study practice versus this page’s explanatory implementation</caption><thead><tr><th>Method</th><th>Source evidence</th><th>Implementation here / limit</th></tr></thead><tbody><tr><th scope="row">Allocation and ITT</th><td>Protocol: individual 1:1 allocation, blocks of four within villages; all-assigned analysis.</td><td>Crude risks retain all 2,278 records per arm. Complete-randomization teaching labs use a different, explicitly synthetic design.</td></tr><tr><th scope="row">Binary comparisons</th><td>Protocol / reporting summary: χ² or Fisher; SAS 9.4.</td><td>Uncorrected Pearson and two-sided Fisher are independently computed. Test-label disagreements remain visible.</td></tr><tr><th scope="row">Effect intervals</th><td>Published risk ratios and 95% intervals.</td><td>Katz log-RR and Wald RD approximations are stated explicitly. The exact original CI algorithm is unknown; some endpoints differ.</td></tr><tr><th scope="row">Planning and monitoring</th><td>Protocol: 8% control risk, 20% relative reduction, 80% power, planned 8,442 total; interim nominal boundaries discussed.</td><td>Fixed-sample normal approximation below is explanatory. It does not reconstruct actual DSMB data or repeated-look adjusted inference.</td></tr><tr><th scope="row">Covariate adjustment</th><td>Protocol proposed regression / stepwise selection if imbalance appeared.</td><td>Not evidence that a particular adjusted model was fitted. No such model is claimed here.</td></tr></tbody></table></div><details><summary>Binary tests: Pearson statistic and the conditional exact model</summary><div class="formula">$$X^2=\sum_{r,c}\frac{(O_{rc}-E_{rc})^2}{E_{rc}},\qquad E_{rc}=\frac{n_{r+}n_{+c}}N,\qquad X^2\overset{H_0}{\approx}\chi^2_1.$$ $$\Pr(A=k\mid m,n_1,n_0)=\frac{\binom{n_1}{k}\binom{n_0}{m-k}}{\binom{n_1+n_0}{m}}.$$</div><p>Here m is the total number of events. The two-sided Fisher p-value sums tables with conditional probability no greater than the observed table’s probability. It differs from an uncorrected large-sample χ² p-value; small-cell comparisons need particular care.</p></details><details><summary>Planning approximation and the link to the density plot</summary><div class="formula">$$n\approx\frac{\left[z_{1-\alpha/2}\sqrt{2\bar p(1-\bar p)}+z_{1-\beta}\sqrt{p_0(1-p_0)+p_1(1-p_1)}\right]^2}{(p_1-p_0)^2},\quad\bar p=(p_0+p_1)/2.$$ $$s_0=\sqrt{2\bar p(1-\bar p)/n},\quad s_A=\sqrt{\{p_0(1-p_0)+p_1(1-p_1)\}/n},\quad c=z_{1-\alpha/2}s_0.$$ $$\text{Power}\approx\Phi\!\left(\frac{-c-(p_1-p_0)}{s_A}\right)+1-\Phi\!\left(\frac{c-(p_1-p_0)}{s_A}\right).$$</div><p>This standard equal-arm approximation omits continuity and sequential corrections. Its result need not equal the protocol’s sample-size calculation. Protocol planning p₀ = .08 and p₁ = .064 give about 4,100 per arm here, versus 4,221 planned per arm. The difference is left explicit.</p></details><p class="source-note">Sources: <a href="2026-08-09-rct-visual-guide/sources/Panigrahi_et_al._RCT_Protocol_Synbiotic_study.pdf">Protocol version 2, July 15, 2008, especially pp. 21–33</a>; Nature reporting summary and public tables; <a href="https://doi.org/10.1038/nature25006">corrigendum</a>. Ordinary fixed-sample intervals here are not sequentially adjusted.</p></section>'''
